-- Contact page header: headline, intro and actions on the left (jump to the
-- form / areas of interest), a panel of the three reasons to get in touch on
-- the right; styled by the pc-hero* classes in app/builder.css. Areas of
-- interest gets an anchor id. Previous layout kept as a page revision.

INSERT INTO public.cms_page_revisions (page_id, title, content, seo, reason)
SELECT id, title || ' (before header redesign)', published_content, seo, 'publish'
FROM public.cms_pages
WHERE slug = 'contact'
  AND published_content->'sections'->0->>'id' = 'xzwya0i6y'
  AND published_content->'sections'->0->'children'->0->>'id' = 'xksjqmj8e'
  AND published_content->'sections'->2->>'id' = 'xku00t5fb';

UPDATE public.cms_pages
SET content = jsonb_set(jsonb_set(content, '{sections,0}', $pch${"id":"xzwya0i6y","type":"section","props":{"tone":"light","label":"Page header","width":"boxed","contentAlign":"left","verticalAlign":"top"},"advanced":{"className":"pc-hero"},"style":{"mobile":{"padding":{"top":"56px","bottom":"56px"}},"desktop":{"padding":{"top":"96px","bottom":"96px"}}},"children":[{"id":"xksjqmj8e","type":"columns","props":{"ratio":"3-2","stackOn":"tablet","reverseOnStack":false},"style":{"desktop":{"gap":"72px","alignItems":"center"},"tablet":{"gap":"44px"}},"children":[{"id":"xyhqqamh8","type":"column","props":{},"children":[{"id":"xx8z4axft","type":"heading","props":{"text":"Get in touch","level":"p","preset":"eyebrow"},"animation":{"type":"fade","easing":"ease-out","duration":700}},{"id":"xoz592iyu","type":"heading","props":{"text":"Let's build healthier communities together.","level":"h1","preset":"default"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":80}},{"id":"x6i8asi8m","type":"paragraph","props":{"size":"lead","text":"Whether you are interested in collaborating on research, exploring partnership opportunities, or joining the PEARL team, we would be happy to connect.","muted":true},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160}},{"id":"xpchbtn01","type":"group","props":{"direction":"row","wrap":true},"style":{"desktop":{"gap":"14px 28px","alignItems":"center"}},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":240},"children":[{"id":"xpchbtn02","type":"button","props":{"label":"Send us a message","link":{"href":"#send-a-message"},"variant":"light","size":"lg","align":"left","icon":true}},{"id":"xpchbtn03","type":"button","props":{"label":"See areas of interest","link":{"href":"#areas-of-interest"},"variant":"link","size":"md","align":"left","icon":true}}]}]},{"id":"xbus31x9r","type":"column","props":{},"advanced":{"className":"pc-hero-panel"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":200},"children":[{"id":"xpchpan01","type":"heading","props":{"text":"We'd love to hear about","level":"p","preset":"eyebrow"}},{"id":"xpchpan02","type":"richtext","props":{"html":"<ul><li><p><strong>Research collaborations</strong></p><p>Co-designing studies, evaluations, and evidence syntheses.</p></li><li><p><strong>Community &amp; health-system partnerships</strong></p><p>Working together on shared health and social challenges.</p></li><li><p><strong>Students &amp; careers</strong></p><p>Graduate projects, research assistant roles, and <a href=\"/careers\">open positions</a>.</p></li></ul>"}}]}]}]}$pch$::jsonb), '{sections,2,advanced}', '{"className":"pc-interests","htmlId":"areas-of-interest"}'::jsonb, true),
    published_content = jsonb_set(jsonb_set(published_content, '{sections,0}', $pch${"id":"xzwya0i6y","type":"section","props":{"tone":"light","label":"Page header","width":"boxed","contentAlign":"left","verticalAlign":"top"},"advanced":{"className":"pc-hero"},"style":{"mobile":{"padding":{"top":"56px","bottom":"56px"}},"desktop":{"padding":{"top":"96px","bottom":"96px"}}},"children":[{"id":"xksjqmj8e","type":"columns","props":{"ratio":"3-2","stackOn":"tablet","reverseOnStack":false},"style":{"desktop":{"gap":"72px","alignItems":"center"},"tablet":{"gap":"44px"}},"children":[{"id":"xyhqqamh8","type":"column","props":{},"children":[{"id":"xx8z4axft","type":"heading","props":{"text":"Get in touch","level":"p","preset":"eyebrow"},"animation":{"type":"fade","easing":"ease-out","duration":700}},{"id":"xoz592iyu","type":"heading","props":{"text":"Let's build healthier communities together.","level":"h1","preset":"default"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":80}},{"id":"x6i8asi8m","type":"paragraph","props":{"size":"lead","text":"Whether you are interested in collaborating on research, exploring partnership opportunities, or joining the PEARL team, we would be happy to connect.","muted":true},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":160}},{"id":"xpchbtn01","type":"group","props":{"direction":"row","wrap":true},"style":{"desktop":{"gap":"14px 28px","alignItems":"center"}},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":240},"children":[{"id":"xpchbtn02","type":"button","props":{"label":"Send us a message","link":{"href":"#send-a-message"},"variant":"light","size":"lg","align":"left","icon":true}},{"id":"xpchbtn03","type":"button","props":{"label":"See areas of interest","link":{"href":"#areas-of-interest"},"variant":"link","size":"md","align":"left","icon":true}}]}]},{"id":"xbus31x9r","type":"column","props":{},"advanced":{"className":"pc-hero-panel"},"animation":{"type":"slide-up","easing":"ease-out","duration":700,"delay":200},"children":[{"id":"xpchpan01","type":"heading","props":{"text":"We'd love to hear about","level":"p","preset":"eyebrow"}},{"id":"xpchpan02","type":"richtext","props":{"html":"<ul><li><p><strong>Research collaborations</strong></p><p>Co-designing studies, evaluations, and evidence syntheses.</p></li><li><p><strong>Community &amp; health-system partnerships</strong></p><p>Working together on shared health and social challenges.</p></li><li><p><strong>Students &amp; careers</strong></p><p>Graduate projects, research assistant roles, and <a href=\"/careers\">open positions</a>.</p></li></ul>"}}]}]}]}$pch$::jsonb), '{sections,2,advanced}', '{"className":"pc-interests","htmlId":"areas-of-interest"}'::jsonb, true),
    updated_at = now()
WHERE slug = 'contact'
  AND published_content->'sections'->0->>'id' = 'xzwya0i6y'
  AND published_content->'sections'->0->'children'->0->>'id' = 'xksjqmj8e'
  AND published_content->'sections'->2->>'id' = 'xku00t5fb'
  AND content = published_content;
